from hera.analysis import open_run, resolve_channels, current_channel, sdh_onset, sdh_fft
import numpy as np
from scipy.signal import find_peaks
for i in (6,7):
 r=open_run(f'data/{i}'); mc=r.meta['measurement_config']; ch=resolve_channels(r.meta); cc=current_channel(ch); vc=next(x for x in ch if x.cid=='sr1'); I=r.col(cc.col)/cc.gain; R=np.abs((r.col(vc.col)/vc.gain)/I); B=r.col('magnet_field');
 print('\nRUN',i,'COLS',r.cols,'BIAS',r.meta['instruments']['sr1']['snapshot']['parameters']['amplitude']['value'],'SENS',r.meta['instruments']['sr1']['snapshot']['parameters']['sensitivity']['value'])
